def fix(s):
    s=' '+s+' '
    for a,b in PAIRS:
        if a in ('roid','nggi','dak','ndakan'):
            s=re.sub(r'(?<=\s)'+a+r'(?=[\s\.,;:?/)])',b,s)
            s=re.sub(r'(\w) '+a+r'(?=[\s\.,;:?/)])',lambda m:m.group(0),s)
        else: s=s.replace(a,b)
    s=s.replace('tivitastivitas','tivitas')
    return re.sub(r'\s+',' ',s).strip()
